export const Website = () => {
  const { settings } = usePageContext();
  const { app } = settings;

  return app?.appName;
};

export const AppName = () => {
  const { settings } = usePageContext();
  const { app } = settings;
  return app?.appName;
};

export const Logo = (props) => {
  const { settings, baseUrl } = usePageContext();
  const { app } = settings;

  console.log('appappLogo',APIURLS.imageUrl + app?.logo)
  // console.log('appappLogo1', `${APIURLS.imageUrl}/${app?.logo}`);

  return (<ImageComponent
    src={APIURLS.imageUrl + app?.logo}
    width={150}
    height={50}
    layout="intrinsic"
    alt="logo"
    onError={handleSVGError}
    // style={{ width: 'var(--logo-width)' , height:'var( --logo-height)' }}
    {...props}
  />);
};

